-- mod-temucraft-travel: the DBC rows this module needs, for the server (AzerothCore reads the *_dbc tables on top of
-- its DBC files). The client needs the same rows: see client/ in this module. Re-runnable.
-- spell_dbc: 1 row(s) mod-temucraft-travel
DELETE FROM `spell_dbc` WHERE `ID` IN (95020);

-- spell_dbc: 20 row(s) mod-temucraft-travel, Stones and Scrolls of Homecoming (97151-97170)
DELETE FROM `spell_dbc` WHERE `ID` BETWEEN 97151 AND 97170;

-- spellcategory_dbc: the two cooldown groups (1820 stones, 1821 scrolls), apart from the hearthstone (1176)
DELETE FROM `spellcategory_dbc` WHERE `ID` IN (1820, 1821);
